@Composable
private fun EventCard(
    title: String,
    maulana: String,
    location: String,
    date: String,
    time: String,
    isLive: Boolean,
    onClick: () -> Unit = {}
) {
    Card(
        onClick = onClick,
        modifier = Modifier
            .width(280.dp)
            .shadow(
                elevation = 6.dp,
                shape = RoundedCornerShape(16.dp),
                ambientColor = CardShadow,
                spotColor = CardShadow
            ),
        shape = RoundedCornerShape(16.dp),
        colors = CardDefaults.cardColors(
            containerColor = MaterialTheme.colorScheme.surface
        )
    ) {
        Column {
            // Top accent strip with mosque illustration
            Box(
                modifier = Modifier
                    .fillMaxWidth()
                    .height(100.dp)
                    .background(
                        brush = Brush.horizontalGradient(
                            colors = listOf(PrimaryTeal, PrimaryTealDark)
                        )
                    ),
                contentAlignment = Alignment.Center
            ) {
                // Decorative pattern
                Canvas(modifier = Modifier.matchParentSize()) {
                    val w = size.width
                    val h = size.height
                    // Islamic arch pattern
                    drawArc(
                        color = Color.White.copy(alpha = 0.08f),
                        startAngle = 180f,
                        sweepAngle = 180f,
                        useCenter = true,
                        topLeft = Offset(w * 0.3f, h * 0.1f),
                        size = androidx.compose.ui.geometry.Size(w * 0.4f, h * 0.8f)
                    )
                    drawArc(
                        color = Color.White.copy(alpha = 0.06f),
                        startAngle = 180f,
                        sweepAngle = 180f,
                        useCenter = true,
                        topLeft = Offset(w * 0.1f, h * 0.3f),
                        size = androidx.compose.ui.geometry.Size(w * 0.2f, h * 0.6f)
                    )
                    drawArc(
                        color = Color.White.copy(alpha = 0.06f),
                        startAngle = 180f,
                        sweepAngle = 180f,
                        useCenter = true,
                        topLeft = Offset(w * 0.7f, h * 0.3f),
                        size = androidx.compose.ui.geometry.Size(w * 0.2f, h * 0.6f)
                    )
                }

                // Live badge
                if (isLive) {
                    Box(
                        modifier = Modifier
                            .align(Alignment.TopEnd)
                            .padding(Spacing.small)
                    ) {
                        Surface(
                            shape = RoundedCornerShape(12.dp),
