// ──────────────────────────────────────────────────────────────────────────
// Home Screen - Main shell with bottom navigation
// ──────────────────────────────────────────────────────────────────────────

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun HomeScreen(
    modifier: Modifier = Modifier,
    onEventClick: (Int) -> Unit = {},
    onMaulanaClick: (Int) -> Unit = {},
    onNotificationsClick: () -> Unit = {},
    onLogoutClick: () -> Unit = {}
) {
    val pagerState = rememberPagerState(initialPage = 0) { 4 }
    val coroutineScope = rememberCoroutineScope()
    val context = LocalContext.current
    var backPressedOnce by remember { mutableStateOf(false) }

    // Back press: non-Home tab → go to Home; Home tab → double-press to exit
    BackHandler(enabled = true) {
        if (pagerState.currentPage != 0) {
            coroutineScope.launch {
                pagerState.animateScrollToPage(0)
            }
        } else if (backPressedOnce) {
            (context as? android.app.Activity)?.finish()
        } else {
            backPressedOnce = true
            Toast.makeText(context, "Tap back again to exit", Toast.LENGTH_SHORT).show()
            coroutineScope.launch {
                kotlinx.coroutines.delay(2000)
                backPressedOnce = false
            }
        }
    }

    Scaffold(
        modifier = modifier.fillMaxSize(),
        bottomBar = {
            CompactBottomNavBar(
                selectedIndex = pagerState.currentPage,
                onTabSelected = { index ->
                    coroutineScope.launch {
                        pagerState.animateScrollToPage(index)
                    }
                }
            )
        },
        containerColor = MaterialTheme.colorScheme.background
    ) { innerPadding ->
        HorizontalPager(
            state = pagerState,
            modifier = Modifier
                .fillMaxSize()
                .padding(innerPadding),
            beyondViewportPageCount = 1,
            key = { it }
        ) { page ->
            when (page) {
                0 -> HomeContent(
                    onEventClick = onEventClick,
                    onMaulanaClick = onMaulanaClick,
                    onNotificationsClick = onNotificationsClick
                )
                1 -> EventsScreen(onEventClick = onEventClick)
                2 -> MaulanaScreen(onMaulanaClick = onMaulanaClick)
                3 -> ProfileScreen(
                    onNotificationsClick = onNotificationsClick,
                    onLogoutClick = onLogoutClick
                )
                else -> HomeContent(
                    onEventClick = onEventClick,
                    onMaulanaClick = onMaulanaClick,
                    onNotificationsClick = onNotificationsClick
                )
            }
        }
    }
}

