            }

            // Content
            Column(
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(Spacing.medium)
                    .padding(top = Spacing.small)
            ) {
                Text(
                    text = title,
                    style = MaterialTheme.typography.titleMedium,
