// ══════════════════════════════════════════════════════════════════════════
// Compact Bottom Navigation Bar
// ══════════════════════════════════════════════════════════════════════════

private data class NavItem(
    val label: String,
    val selectedIcon: ImageVector,
    val unselectedIcon: ImageVector
)

@Composable
private fun CompactBottomNavBar(
    selectedIndex: Int,
    onTabSelected: (Int) -> Unit
) {
    val items = listOf(
        NavItem("Home", Icons.Filled.Home, Icons.Outlined.Home),
        NavItem("Events", Icons.Filled.DateRange, Icons.Outlined.DateRange),
        NavItem("Maulana", Icons.Filled.Person, Icons.Outlined.Person),
        NavItem("Profile", Icons.Filled.AccountCircle, Icons.Outlined.AccountCircle)
    )

    Surface(
        modifier = Modifier.fillMaxWidth(),
        color = MaterialTheme.colorScheme.surface,
        shadowElevation = 8.dp
    ) {
        Row(
            modifier = Modifier
                .fillMaxWidth()
                .navigationBarsPadding()
                .height(56.dp),
            horizontalArrangement = Arrangement.SpaceAround,
            verticalAlignment = Alignment.CenterVertically
        ) {
            items.forEachIndexed { index, item ->
                CompactNavItem(
                    item = item,
                    isSelected = selectedIndex == index,
                    onClick = { onTabSelected(index) }
                )
            }
        }
    }
}

@Composable
private fun CompactNavItem(
    item: NavItem,
    isSelected: Boolean,
    onClick: () -> Unit
) {
    val iconColor by animateColorAsState(
        targetValue = if (isSelected) PrimaryTeal else MaterialTheme.colorScheme.onSurfaceVariant,
        animationSpec = tween(250),
        label = "navIconColor"
    )
    val labelColor by animateColorAsState(
        targetValue = if (isSelected) PrimaryTeal else MaterialTheme.colorScheme.onSurfaceVariant,
        animationSpec = tween(250),
        label = "navLabelColor"
    )
    val indicatorAlpha by animateFloatAsState(
        targetValue = if (isSelected) 0.12f else 0f,
        animationSpec = tween(250),
        label = "navIndicator"
    )

    Column(
        modifier = Modifier
            .clip(RoundedCornerShape(12.dp))
            .clickable(
                interactionSource = remember { MutableInteractionSource() },
                indication = null,
                onClick = onClick
            )
            .padding(horizontal = 16.dp, vertical = 4.dp),
        horizontalAlignment = Alignment.CenterHorizontally,
        verticalArrangement = Arrangement.Center
    ) {
        Box(
            modifier = Modifier
                .clip(RoundedCornerShape(12.dp))
                .background(PrimaryTeal.copy(alpha = indicatorAlpha))
                .padding(horizontal = 12.dp, vertical = 2.dp),
            contentAlignment = Alignment.Center
        ) {
            Icon(
                imageVector = if (isSelected) item.selectedIcon else item.unselectedIcon,
                contentDescription = item.label,
                tint = iconColor,
                modifier = Modifier.size(22.dp)
            )
        }
        Text(
            text = item.label,
            style = MaterialTheme.typography.labelSmall,
            fontSize = 10.sp,
            fontWeight = if (isSelected) FontWeight.Bold else FontWeight.Normal,
            color = labelColor,
            maxLines = 1
        )
    }
}

