// ──────────────────────────────────────────────────────────────────────────
// Profile Screen
// ──────────────────────────────────────────────────────────────────────────

@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun ProfileScreen(
    modifier: Modifier = Modifier,
    onNotificationsClick: () -> Unit = {}
) {
    LazyColumn(
        modifier = modifier
            .fillMaxSize()
            .background(MaterialTheme.colorScheme.background),
        contentPadding = PaddingValues(bottom = Spacing.medium)
    ) {
        // ── Profile Header ───────────────────────────────────────────
        item {
            ProfileHeader()
        }

        // ── Stats Row ────────────────────────────────────────────────
        item {
            ProfileStatsRow()
        }

        // ── Account Section ──────────────────────────────────────────
        item {
            ProfileSectionTitle("Account")
        }
        item {
            ProfileMenuGroup(
                items = listOf(
                    ProfileMenuItem(
                        icon = Icons.Outlined.Person,
                        title = "Edit Profile",
                        subtitle = "Update your information",
                        color = PrimaryTeal
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Notifications,
                        title = stringResource(R.string.settings_notifications),
                        subtitle = "Manage notification preferences",
                        color = AccentOrange,
                        onClick = onNotificationsClick
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Lock,
                        title = "Privacy & Security",
                        subtitle = "Password, account security",
                        color = InfoBlue
                    )
                )
            )
        }

        // ── Activity Section ─────────────────────────────────────────
        item {
            ProfileSectionTitle("My Activity")
        }
        item {
            ProfileMenuGroup(
                items = listOf(
                    ProfileMenuItem(
                        icon = Icons.Outlined.FavoriteBorder,
                        title = "Saved Events",
                        subtitle = "12 events saved",
                        color = ErrorRed,
                        badge = "12"
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Person,
                        title = "Following",
                        subtitle = "8 scholars followed",
                        color = PrimaryTeal,
                        badge = "8"
                    ),
                    ProfileMenuItem(
                        icon = Icons.Filled.DateRange,
                        title = "My Reminders",
                        subtitle = "3 upcoming reminders",
                        color = SecondaryGreen,
                        badge = "3"
                    ),
                    ProfileMenuItem(
                        icon = Icons.Filled.Star,
                        title = "Event History",
                        subtitle = "Events you attended",
                        color = AccentOrange
                    )
                )
            )
        }

        // ── Preferences Section ──────────────────────────────────────
        item {
            ProfileSectionTitle("Preferences")
        }
        item {
            ProfileMenuGroup(
                items = listOf(
                    ProfileMenuItem(
                        icon = Icons.Outlined.Place,
                        title = stringResource(R.string.settings_language),
                        subtitle = "English",
                        color = VerifiedBadge
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Info,
                        title = stringResource(R.string.settings_theme),
                        subtitle = "System default",
                        color = PrimaryTealDark
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.LocationOn,
                        title = "Location",
                        subtitle = "Dhaka, Bangladesh",
                        color = SecondaryGreen
                    )
                )
            )
        }

        // ── Support Section ──────────────────────────────────────────
        item {
            ProfileSectionTitle("Support")
        }
        item {
            ProfileMenuGroup(
                items = listOf(
                    ProfileMenuItem(
                        icon = Icons.Outlined.Info,
                        title = stringResource(R.string.settings_about),
                        subtitle = "About MahfilHub v1.0",
                        color = PrimaryTeal
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Email,
                        title = "Help & Feedback",
                        subtitle = "Contact us, report issues",
                        color = InfoBlue
                    ),
                    ProfileMenuItem(
                        icon = Icons.Outlined.Share,
                        title = "Share App",
                        subtitle = "Invite friends to MahfilHub",
                        color = AccentOrange
                    )
                )
            )
        }

        // ── Logout Button ────────────────────────────────────────────
        item {
            LogoutButton()
        }

        // ── App Version ──────────────────────────────────────────────
        item {
            Text(
                text = "MahfilHub v1.0.0",
                modifier = Modifier
                    .fillMaxWidth()
                    .padding(vertical = Spacing.medium),
                style = MaterialTheme.typography.labelSmall,
                color = MaterialTheme.colorScheme.onSurfaceVariant,
                textAlign = TextAlign.Center
            )
        }
    }
}

